CREATE TABLE IF NOT EXISTS students  (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL, department VARCHAR(80), semester INT);
CREATE TABLE IF NOT EXISTS faculty   (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL, department VARCHAR(80));
CREATE TABLE IF NOT EXISTS courses   (id SERIAL PRIMARY KEY, code VARCHAR(20) NOT NULL, title VARCHAR(120) NOT NULL, credits INT, faculty_id INT);
CREATE TABLE IF NOT EXISTS resources (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, res_type VARCHAR(20) NOT NULL, capacity INT);
CREATE TABLE IF NOT EXISTS events    (id SERIAL PRIMARY KEY, title VARCHAR(120) NOT NULL, event_date VARCHAR(20), venue VARCHAR(100));
CREATE TABLE IF NOT EXISTS bookings  (id SERIAL PRIMARY KEY, resource_id INT NOT NULL, booked_by VARCHAR(100) NOT NULL, slot VARCHAR(30) NOT NULL, UNIQUE (resource_id, slot));
CREATE TABLE IF NOT EXISTS books (id SERIAL PRIMARY KEY, title VARCHAR(150) NOT NULL, author VARCHAR(100) NOT NULL, category VARCHAR(60), copies INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS loans (id SERIAL PRIMARY KEY, book_id INT NOT NULL, member VARCHAR(100) NOT NULL, issue_date VARCHAR(20) NOT NULL, due_date VARCHAR(20) NOT NULL, returned BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
